#!/bin/sh
# Writes Sources/CodecBlueCore/GeneratedVersion.swift from the git tag, so that the binary knows
# which release it is.
#
#   scripts/version.sh            print the version, change nothing
#   scripts/version.sh --write    write the file, and print the version
#
# Why a generated file and not `git describe` at run time: the binary has to know its own version on
# a machine with no git, no checkout and no network, which is every machine that runs a release. The
# version has to be inside the executable.
#
# The file is committed with a development default, so a checkout that never runs this script still
# compiles and still tells the truth ("0.0.0-development"). `--write` overwrites it, and the caller
# puts it back when the build is done — `scripts/package.sh` and `make release` do exactly that, so
# `git status` stays clean and a release build cannot leave a version number behind that the next
# commit would carry.
set -e

HERE=$(cd "$(dirname "$0")/.." && pwd)
TARGET="$HERE/Sources/CodecBlueCore/GeneratedVersion.swift"

# `git describe` is the right tool and the only one that answers the interesting question:
#
#   on a tag          -> "v1.2.0"
#   three commits on  -> "v1.2.0-3-gabc1234"   (a build between releases: honest, and sortable)
#   no tags at all    -> falls back to a bare hash, which is not a version and is labelled as such
#
# `--dirty` is deliberately not used: a build from a modified tree is not a release, and marking it
# dirty in the version string would let two different binaries claim the same version. The release
# script checks for a clean tree instead, and refuses.
version=$(git -C "$HERE" describe --tags --always 2>/dev/null || echo "")
case "$version" in
    v[0-9]*) version=${version#v} ;;
    [0-9]*) ;;
    *) version="0.0.0-development" ;;
esac
commit=$(git -C "$HERE" rev-parse --short HEAD 2>/dev/null || echo "")

if [ "${1:-}" != "--write" ]; then
    printf '%s\n' "$version"
    exit 0
fi

cat > "$TARGET" <<SWIFT
import Foundation

// Generated by scripts/version.sh for this build. Do not edit, and do not commit the change: the
// committed version of this file says "0.0.0-development", which is what a checkout is.
public enum GeneratedVersion {
    public static let tag = "$version"
    public static let commit = "$commit"
}
SWIFT

printf '%s\n' "$version"
